const { exec } = require('child_process');

function deleteUserAccount(username) {
  const command = `userdel -r ${username}`;
  exec(command, (error, stdout, stderr) => {
    if (error) {
      console.error(`Failed to delete user: ${error.message}`);
      return;
    }
    console.log(`Account deleted: ${username}`);
  });
}

import java.io.*;

public class InvoiceService {
    public Invoice processInvoice(byte[] invoiceBytes) throws IOException, ClassNotFoundException {
        ByteArrayInputStream bis = new ByteArrayInputStream(invoiceBytes);
        ObjectInputStream ois = new ObjectInputStream(bis);
        Invoice invoice = (Invoice) ois.readObject();
        ois.close();
        invoice.calculateTotal();
        invoice.applyDiscounts();
        return invoice;
    }
}

const express = require('express');
const path = require('path');
const fs = require('fs');
const app = express();
const DOCS_DIR = '/var/www/docs';

app.get('/document/:filename', (req, res) => {
    const filename = req.params.filename;
    const filePath = path.join(DOCS_DIR, filename);
    fs.readFile(filePath, 'utf8', (err, data) => {
        if (err) {
            res.status(404).send('File not found');
            return;
        }
        res.type('text/plain').send(data);
    });
});
